INSERT INTO public.session_blocks(block_id,session_id,block_type,title,content,workout_format,timer_config,coach_notes,position) VALUES
 ('b1800001-0000-4000-8000-000000000001','APOLLO-W8-MON-R1','warm_up','Apollo Shoulder Balance Warm-Up','Thoracic extension over foam roller: 5 slow reps at 2-3 positions; Open-book rotation: 6/side; Serratus wall slide + reach: 2x8; Wall Y/lower-trap raise: 2x8-10 very light; Single-arm cable/band row with reach: 2x10/side; then 2-4 progressive sets for first compound.','none',NULL,'Do not cue permanent shoulders down and back.',1),
 ('b1800002-0000-4000-8000-000000000002','APOLLO-W8-MON-R1','strength','Phase II absorb strength','Approximately 60-70% normal resistance volume; all resistance work is approximately 2-3 RIR; controlled light neck work.','none',NULL,NULL,2),
 ('b1800003-0000-4000-8000-000000000003','APOLLO-W8-TUE-R1','warm_up','Run preparation','5 minutes brisk walk/easy jog before Zone 2.','none',NULL,NULL,1),
 ('b1800004-0000-4000-8000-000000000004','APOLLO-W8-TUE-R1','conditioning','Zone 2 run','50 minutes conversational Zone 2 at RPE 3-4.','intervals','{"work_seconds":3000,"tracking":["distance","average_pace","average_hr"],"intensity":"zone_2"}'::jsonb,'Track distance, average pace and average HR.',2),
 ('b1800005-0000-4000-8000-000000000005','APOLLO-W8-TUE-R1','core','Hanging Leg Raise','2 x 8-12; rest 60-90 seconds.','none',NULL,NULL,3),
 ('b1800006-0000-4000-8000-000000000006','APOLLO-W8-TUE-R1','cool_down','Full Apollo mobility flow','Knee-to-wall ankle rocks 2x8/side; 90/90 hip switches 2x8/side; adductor rock-back 2x8/side; half-kneeling hip-flexor stretch with reach 45 sec/side; deep-squat pry 2x30 sec; open-book rotation 6/side; wall slide with reach 2x8; passive hang 2x30 sec.','none',NULL,NULL,4),
 ('b1800007-0000-4000-8000-000000000007','APOLLO-W8-WED-R1','warm_up','Lower-body warm-up','Easy cardio 5 min; knee-to-wall ankle rocks 8/side; 90/90 hip switches 8/side; adductor rock-backs 8/side; glute bridge 2x10; bodyweight squat 2x8; progressive squat and RDL warm-up sets.','none',NULL,NULL,1),
 ('b1800008-0000-4000-8000-000000000008','APOLLO-W8-WED-R1','strength','Phase II absorb Racehorse strength','Approximately 60-70% normal resistance volume; all unilateral prescriptions are per leg; all resistance work is approximately 2-3 RIR.','none',NULL,NULL,2),
 ('b1800009-0000-4000-8000-000000000009','APOLLO-W8-THU-R1','warm_up','Interval warm-up','12-minute easy jog; leg swings 10/side; A-skips 2x20m; 3x20-second strides.','none',NULL,NULL,1),
 ('b1800010-0000-4000-8000-000000000010','APOLLO-W8-THU-R1','conditioning','Controlled 10K-effort intervals','4 x 3 minutes at controlled approximately 10K effort; 2-minute easy-jog recoveries.','intervals','{"rounds":4,"work_seconds":180,"recovery_seconds":120,"tracking":["interval_pace"],"effort":"controlled_approximately_10k","vo2":false}'::jsonb,'Deliberately not a VO2 workout; controlled pacing.',2),
 ('b1800011-0000-4000-8000-000000000011','APOLLO-W8-THU-R1','cool_down','Easy-jog cooldown','10 minutes easy jogging.','none','{"work_seconds":600}'::jsonb,NULL,3),
 ('b1800012-0000-4000-8000-000000000012','APOLLO-W8-FRI-R1','warm_up','Apollo Shoulder Balance Warm-Up','Thoracic extension over foam roller: 5 slow reps at 2-3 positions; Open-book rotation: 6/side; Serratus wall slide + reach: 2x8; Wall Y/lower-trap raise: 2x8-10 very light; Single-arm cable/band row with reach: 2x10/side; then 2-4 progressive sets for first compound.','none',NULL,NULL,1),
 ('b1800013-0000-4000-8000-000000000013','APOLLO-W8-FRI-R1','strength','Phase II absorb Apollo Sculpt','Approximately 60-70% normal resistance volume; all resistance work is approximately 2-3 RIR, including light neck work.','none',NULL,'Isolation rest 60-90 seconds; neck rest 45-60 seconds.',2),
 ('b1800014-0000-4000-8000-000000000014','APOLLO-W8-SAT-R1','warm_up','Athletic warm-up','Easy cardio 5 min; ankle pogos 2x20; World''s greatest stretch 5/side; glute bridge 10; jump landing rehearsal 2x3; progressive trap-bar warm-up sets.','none',NULL,NULL,1),
 ('b1800015-0000-4000-8000-000000000015','APOLLO-W8-SAT-R1','strength','Reduced-fatigue strength and power','Rotational throws and box jumps use full recovery; trap-bar deadlift is approximately 3 RIR; no conditioning.','none',NULL,NULL,2),
 ('b1800016-0000-4000-8000-000000000016','APOLLO-W8-SUN-R1','warm_up','Run preparation','5 minutes brisk walk/easy jog before Zone 2.','none',NULL,NULL,1),
 ('b1800017-0000-4000-8000-000000000017','APOLLO-W8-SUN-R1','conditioning','Zone 2 run','65 minutes conversational Zone 2 at RPE 3-4.','intervals','{"work_seconds":3900,"tracking":["distance","average_pace","average_hr"],"intensity":"zone_2"}'::jsonb,'Track distance, pace and HR.',2),
 ('b1800018-0000-4000-8000-000000000018','APOLLO-W8-SUN-R1','cool_down','Full Apollo mobility flow','Knee-to-wall ankle rocks 2x8/side; 90/90 hip switches 2x8/side; adductor rock-back 2x8/side; half-kneeling hip-flexor stretch with reach 45 sec/side; deep-squat pry 2x30 sec; open-book rotation 6/side; wall slide with reach 2x8; passive hang 2x30 sec.','none',NULL,NULL,3);
