DO $$
DECLARE v_existing integer; v_exact integer;
BEGIN
 SELECT count(*) INTO v_existing FROM public.performance_protocols WHERE protocol_id LIKE 'APOLLO-W8-%-R1';
 SELECT count(*) INTO v_exact FROM public.performance_protocols WHERE (protocol_id,name,authoring_scope,organisation_id,lifecycle_status) IN (
  ('APOLLO-W8-MON-R1','Apollo Strength','organisation','apollo-dogfood','draft'),('APOLLO-W8-TUE-R1','Apollo Base','organisation','apollo-dogfood','draft'),('APOLLO-W8-WED-R1','Racehorse Strength','organisation','apollo-dogfood','draft'),('APOLLO-W8-THU-R1','Apollo Engine','organisation','apollo-dogfood','draft'),('APOLLO-W8-FRI-R1','Apollo Sculpt','organisation','apollo-dogfood','draft'),('APOLLO-W8-SAT-R1','Apollo Athletic','organisation','apollo-dogfood','draft'),('APOLLO-W8-SUN-R1','Apollo Long','organisation','apollo-dogfood','draft'));
 IF v_existing = 7 AND v_exact = 7 THEN RETURN; END IF;
 IF v_existing <> 0 THEN RAISE EXCEPTION 'Apollo Week 8 protocol identity/content conflict'; END IF;
END $$;


