DO $$ BEGIN
 IF (SELECT count(*) FROM public.session_blocks WHERE session_id LIKE 'APOLLO-W8-%-R1') <> 18 OR (SELECT count(*) FROM public.session_block_exercises e JOIN public.session_blocks b ON b.block_id=e.block_id WHERE b.session_id LIKE 'APOLLO-W8-%-R1') <> 38 THEN RAISE EXCEPTION 'Apollo Week 8 seed conflict: deterministic content is incomplete or mismatched'; END IF;
END $$;
